**The bug:** when a parallel tick fires after a sibling session has already dispatched a task and launched the worker, the tick must *adopt* the sibling's work — not re-do it. A naive tick re-dispatches (duplicate worker), re-runs the judge (wasted, potentially conflicting verdict), or kills the worker it thinks it owns (orphans/duplicates state). The steward pattern fixes this by gating every mutation behind read-only detection and independent verification, then making exactly one idempotent completion commit.

**The fix** is a gated transaction (`/home/kara/steward/steward.py`, entry point `stew()`):

```python
def stew(cfg: StewardConfig, verifiers=None, git=run_git) -> StewardOutcome:
    with StewardLock(cfg.lock_path, timeout=cfg.lock_timeout):        # 1 tick at a time
        board_stale = is_board_stale(cfg.board_path, cfg.stale_after) # sibling dead? (mtime frozen >3-4 min)
        orphans = find_orphaned_rows(load_board(cfg.board_path), board_stale)
        if not board_stale:
            return outcome("board fresh: sibling alive; standing down")
        for row in orphans:
            # GATE 1 — detect worker commit (read-only; never re-dispatch)
            commit = find_worker_commit(cfg.repo_dir, row.task_id, git=git)
            if commit is None:
                return outcome(f"{row.task_id}: no worker commit; row left open")
            # GATE 2 — independent verification: shim/parity/importer/trailer, all must pass
            verification = verify_commit(commit, verifiers, cfg.verifier_stages)
            if not verification.ok:
                return outcome(f"verification failed at '{verification.stage}'; row left open")
            # GATE 3 — reuse existing judge verdict; NEVER re-run the judge
            verdict = load_judge_verdict(cfg.judge_verdict_path, row.task_id)
            if verdict is None:
                return outcome(f"no reusable verdict; row left open (judge NOT re-run)")
            # GATE 4 — exists-checked completion (idempotent, refuses missing artifacts)
            exists_checked_complete(cfg.workdir, row, commit, verdict)
            # GATE 5 — close orphaned verification tasks (only this task's pending ones)
            outcome.tasks_closed += close_orphaned_verification_tasks(cfg.verification_tasks_path, row.task_id)
            cfg.board_path.write_text("\n".join(r.to_line() for r in rows) + "\n")
            outcome.pushed = commit_and_push(cfg.repo_dir, [cfg.board_path, cfg.verification_tasks_path],
                                             f"steward: adopt orphaned {row.task_id} @ {commit[:12]}", git=git)
            return outcome(f"adopted worker commit {commit[:12]} (verdict {verdict.ref} reused)")
```

Key defensive pieces:

```python
# staleness: a live sibling keeps touching the board JSONL
def is_board_stale(board_path, stale_after=180, now=None):
    return board_staleness_seconds(board_path, now) >= stale_after

# worker-commit detection anchored to the Task-ID trailer, so a baseline/
# dispatch commit that merely *mentions* the task id is never adopted
def find_worker_commit(repo_dir, task_id, git=run_git):
    out = git(repo_dir, "log", "--all", "--format=%H", "--grep", f"Task-ID: {task_id}")
    return out.splitlines()[0] if out.strip() else None

# verification short-circuits on the first failing stage
def verify_commit(commit, verifiers, stages=("shim","parity","importer","trailer")):
    for stage in stages:
        res = verifiers[stage](commit)
        if not res.ok: return res          # e.g. parity: input/output hashes differ
    return VerificationResult(True, stages[-1])

# completion only after artifacts exist on disk; no-op when already complete
def exists_checked_complete(workdir, row, commit, verdict, extra_markers=()):
    for p in [workdir / "result.json", *extra_markers]:
        if not p.exists():
            raise FileNotFoundError(f"exists-check failed: {p} missing")
    row.status, row.worker_commit, row.verdict_ref = "complete", commit, verdict.ref
    row.extra |= {"completed_by": "steward", "verdict_reused": True, "completed_at": int(time.time())}

# flock: a second parallel tick waits/aborts instead of racing (fd never leaks)
class StewardLock:
    def __enter__(self):
        self._fh = open(self.lock_path, "a+")
        try:
            while True:
                try: fcntl.flock(self._fh.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB); return self
                except OSError:
                    if time.monotonic() >= self.deadline: raise TimeoutError(...)
                    time.sleep(0.25)
        except BaseException:
            self._fh.close(); self._fh = None; raise
```

The `do-NOT` list is enforced structurally, not just by convention: dispatch and judge are never invoked anywhere in `stew.py` — the verdict is only *read* (`load_judge_verdict` returns `None` instead of running the judge), worker pids are never signaled, and `commit_and_push` returns `False` when nothing is staged so a second tick pushes nothing.
